/* Danger Wear | Real examples of embroidery & DTF. Shared by PL/EN/DE/FR and all viewports. */
(function () {
  'use strict';
  // Original, separately editable WebP masters are in assets/images/produkcja-metody-realizacje on Drive.
  var sets = {"haft-komputerowy":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"dtf":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
  var langs = {
    pl: { 'haft-komputerowy':'Przykład haftu komputerowego', dtf:'Przykład nadruku DTF' },
    en: { 'haft-komputerowy':'Computer embroidery example', dtf:'DTF transfer example' },
    de: { 'haft-komputerowy':'Beispiel einer Computerstickerei', dtf:'Beispiel eines DTF-Transfers' },
    fr: { 'haft-komputerowy':'Exemple de broderie machine', dtf:'Exemple de transfert DTF' }
  };
  function mount() {
    var language = (document.documentElement.lang || 'pl').slice(0,2);
    var alt = langs[language] || langs.pl;
    Object.keys(sets).forEach(function(method) {
      var panel = document.getElementById(method);
      var img = panel && panel.querySelector('.dw-method-visual > img');
      if (!img) return;
      var files = sets[method];
      var key = 'dw-prod-gallery-last-' + method;
      var prev = -1;
      try { var saved = localStorage.getItem(key); if (saved !== null) prev = Number(saved); } catch (err) {}
      var options = files.map(function(_,i){return i;}).filter(function(i){return i !== prev;});
      var picked = options[Math.floor(Math.random() * options.length)];
      if (picked === undefined) picked = 0;
      var fallback = img.getAttribute('src');
      var selected = files[picked];
      img.onerror = function(){img.onerror=null;if(fallback !== selected)img.src=fallback;};
      img.alt = alt[method] + ' ' + (picked + 1);
      img.decoding = 'async';
      img.src = selected;
      try { localStorage.setItem(key, String(picked)); } catch (err) {}
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mount, {once:true});
  else mount();
})();
